import csv, io, json, os, sys, unicodedata


def nid(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    s = ''.join(c if (unicodedata.category(c)[0] == 'L' or unicodedata.category(c) == 'Nd') else ' ' for c in s)
    return ' '.join(s.split())


def read_batch(path):
    with open(path, encoding='utf-8', newline='') as f:
        text = f.read()
    text = text.replace('\r\n', '\n')
    meta, recs = {}, []
    if path.endswith('.jsonl'):
        first = True
        for line in text.split('\n'):
            if not line.strip():
                continue
            o = json.loads(line)
            if first:
                meta = o
                first = False
                continue
            marks = {}
            for m in o.get('marks', []):
                r = int(m['rank'])
                if 'write_in' in m and m['write_in'] is not None:
                    marks.setdefault(r, []).append(('w', m['write_in']))
                else:
                    marks.setdefault(r, []).append(('c', m['candidate']))
            recs.append((o['ballot'], o['contest'], marks))
    else:
        lines = text.split('\n')
        i = 0
        while i < len(lines) and (lines[i].startswith('#') or not lines[i].strip()):
            l = lines[i]
            if l.startswith('#') and ':' in l:
                k, v = l[1:].split(':', 1)
                meta[k.strip().lower()] = v.strip()
            i += 1
        rows = csv.reader(io.StringIO('\n'.join(lines[i:])))
        header = None
        for row in rows:
            if not row or all(not c.strip() for c in row):
                continue
            if header is None:
                header = [h.strip() for h in row]
                continue
            d = dict(zip(header, row))
            marks = {}
            for h in header:
                if h.startswith('rank') and h[4:].isdigit():
                    r = int(h[4:])
                    cell = d.get(h) or ''
                    for p in cell.split('|'):
                        if not p.strip():
                            continue
                        if p.startswith('WI:'):
                            marks.setdefault(r, []).append(('w', p[3:]))
                        else:
                            marks.setdefault(r, []).append(('c', p))
            recs.append((d['ballot'], d['contest'], marks))
    return meta, recs


def read_ballot(marks, contest):
    """Return list of rankings: ('skip',) / ('pass',) / ('choice', c) / ('over',)"""
    out = []
    seen = set()
    for r in range(1, contest['max_ranks'] + 1):
        cur = set()
        for kind, v in marks.get(r, []):
            if kind == 'w':
                c = contest['wi'].get(norm_text(v))
                if c is not None:
                    cur.add(c)
            else:
                cur.add(nid(v))
        if not cur:
            out.append(('skip',))
            continue
        cur = {c for c in cur if c not in contest['withdrawn']}
        if not cur:
            out.append(('pass',))
            continue
        left = {c for c in cur if c not in seen}
        seen |= cur
        if not left:
            out.append(('skip',))
        elif len(left) == 1:
            out.append(('choice', next(iter(left))))
        else:
            out.append(('over',))
    return out


def count_for(rk, cont):
    n = len(rk)
    for i, x in enumerate(rk):
        t = x[0]
        if t == 'choice':
            if x[1] in cont:
                return x[1]
        elif t == 'over':
            return None
        elif t == 'skip':
            if i + 1 >= n or rk[i + 1][0] == 'skip':
                return None
    return None


def run_contest(contest, ballots):
    cands = contest['active']
    rounds = []
    cont = set(cands)
    winner = None
    total = len(ballots)
    while True:
        tal = {c: 0 for c in cont}
        for rk in ballots:
            c = count_for(rk, cont)
            if c is not None:
                tal[c] += 1
        active = sum(tal.values())
        rd = {'round': len(rounds) + 1, 'tallies': tal, 'exhausted': total - active, 'eliminated': []}
        rounds.append(rd)
        if active == 0:
            break
        win = [c for c, v in tal.items() if v * 2 > active]
        if win:
            winner = win[0]
            break
        if len(cont) == 1:
            winner = next(iter(cont))
            break
        zeros = [c for c in cont if tal[c] == 0]
        if zeros:
            elim = zeros
        else:
            tied = [c for c, v in tal.items() if v == min(tal.values())]
            k = len(rounds) - 2
            while len(tied) > 1 and k >= 0:
                pv = rounds[k]['tallies']
                m = min(pv[c] for c in tied)
                tied = [c for c in tied if pv[c] == m]
                k -= 1
            if len(tied) > 1:
                tied = [max(tied, key=lambda c: contest['lot'].get(c, -1))]
            elim = tied
        rd['eliminated'] = elim
        cont -= set(elim)
    names = contest['names']
    for rd in rounds:
        rd['tallies'] = {names[c]: v for c, v in rd['tallies'].items()}
        rd['eliminated'] = sorted(names[c] for c in rd['eliminated'])
    return {'contest': contest['id'], 'ballots': total,
            'winner': names[winner] if winner is not None else None, 'rounds': rounds}


def main():
    inp, outp = sys.argv[1], sys.argv[2]
    with open(os.path.join(inp, 'election.json'), encoding='utf-8') as f:
        el = json.load(f)
    contests = {}
    order = []
    for c in el['contests']:
        names, wi, withdrawn, active = {}, {}, set(), set()
        for cd in c.get('candidates', []):
            k = nid(cd['id'])
            names[k] = cd['id']
            if cd.get('status') == 'withdrawn':
                withdrawn.add(k)
            else:
                active.add(k)
        for w in c.get('write_ins', []):
            k = nid(w['id'])
            names[k] = w['id']
            active.add(k)
            for t in [w['name']] + list(w.get('aliases', [])):
                wi[norm_text(t)] = k
        lot = {nid(x): i for i, x in enumerate(c.get('lot_order', []))}
        contests[c['id']] = dict(id=c['id'], max_ranks=c['max_ranks'], names=names, wi=wi,
                                 withdrawn=withdrawn, active=active, lot=lot)
        order.append(c['id'])
    cvr = os.path.join(inp, 'cvr')
    best = {}
    for fn in sorted(os.listdir(cvr)):
        p = os.path.join(cvr, fn)
        if not os.path.isfile(p) or not (fn.endswith('.csv') or fn.endswith('.jsonl')):
            continue
        meta, recs = read_batch(p)
        b = str(meta['batch'])
        rev = int(str(meta['revision']).strip())
        if b not in best or rev > best[b][0]:
            best[b] = (rev, str(meta.get('status', 'final')).strip().lower(), recs)
    ballots = {cid: [] for cid in order}
    for rev, status, recs in best.values():
        if status == 'void':
            continue
        for _, cid, marks in recs:
            if cid in contests:
                ballots[cid].append(read_ballot(marks, contests[cid]))
    res = {'election': el['election'], 'contests': [run_contest(contests[c], ballots[c]) for c in order]}
    with open(outp, 'w', encoding='utf-8') as f:
        json.dump(res, f, ensure_ascii=False, indent=1)


main()
